window.RP_SESSION={"id":"S-a334abb8d852","messages":[{"id":"RP-III-0159125","time":"2026-08-25T03:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"의뢰 보상으로 현금 대신 사과 오드비를 조금 얻었다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159126","time":"2026-08-25T03:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 그닥 모양이 예쁘지는 않은 사과 두 개.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159127","time":"2026-08-25T04:00:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이거 가지고 뭘 만들 수 있지?\n메시지가 삭제되었습니다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159128","time":"2026-08-25T04:02:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"일단 사과를 깍둑썰기로 손질한다. 어떤 요리에라도 넣으려면 이게 기본형이니까.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159129","time":"2026-08-25T04:07:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"호밀빵은 찢어먹기 좋은 사이즈로 두 덩이 정도 자르고","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159130","time":"2026-08-25T04:08:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"호밀빵 위에 얇게 자른 치즈를 얹어둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159131","time":"2026-08-25T04:09:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 돼지고기 한 덩어리를 반으로 잘라 불에 달군 팬에 얹는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159132","time":"2026-08-25T04:10:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"지글지글...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159133","time":"2026-08-25T04:11:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"소금과 캐러웨이 씨앗을 좀 뿌린 돼지고기가 버터를 조금 넣은 팬 위에서 갈색 퐁드를 남기며 익어갈 때.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159134","time":"2026-08-25T04:11:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 옆에서 양파를 썰어 둔다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159135","time":"2026-08-25T04:12:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잘 익은 돼지고기를 옆에 치워두고 뚜껑을 덮어 레스팅하며.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159136","time":"2026-08-25T04:12:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"팬에 양파를 넣고 갈색빛이 날 때 까지 볶는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159137","time":"2026-08-25T04:13:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"반 이상 갈색이 돌 때 썰어둔 사과를 투입해 볶는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159138","time":"2026-08-25T04:13:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수분이 나와 퐁드를 긁어내고, 물러져서 소스가 될 때 까지 저어준다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159139","time":"2026-08-25T04:14:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"접시 위에 고기를 얹고, 사이드에 치즈 얹은 빵을 두고","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159140","time":"2026-08-25T04:14:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고기 위에 사과, 양파, 꿀 조금과 소금으로 만든 소스를 부어주면...!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159141","time":"2026-08-25T04:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"고기를 썰어서 포크로 찍어 입에 한 입 넣고.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159142","time":"2026-08-25T04:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사과 오드비 한 모금.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159143","time":"2026-08-25T04:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"우와.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159144","time":"2026-08-25T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"빵을 좀 찢어서 소스를 찍어 입에 넣고.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159145","time":"2026-08-25T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"사과 오드비 또 한 모금.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159146","time":"2026-08-25T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"와우.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159147","time":"2026-08-25T12:12:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"뚜방뚜방.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159148","time":"2026-08-25T12:13:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀입니다.\n\n햄 주니어가 널브러진 로비를 지나... 부엌으로.\n\n오, 고소한 냄새.\n\n뭘까? 카프리제? 아니면 레마?","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159149","time":"2026-08-25T12:13:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 오, 레마네. \"\n\n숀은 레마를 발견하고 귀를 쫑긋. 코는 킁킁.\n\n\" 이번엔 뭐해먹어? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159150","time":"2026-08-25T12:31:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"좋은 냄새에 비몽사몽 부엌으로... 꾸물꾸물 기어가는 햄 주니어.\n\n달팽이같은 모습이네요.","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159151","time":"2026-08-25T12:31:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159152","time":"2026-08-25T12:32:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"맛있는 냄새가 나...\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159153","time":"2026-08-25T12:33:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"주방 방향에서 고기 굽는 냄새와 달달한 냄새가 풍겨오기 시작하자 느릿느릿 걸어나옵니다.","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159154","time":"2026-08-25T12:34:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"레마, 안녕.\"\n\n 레마의 뒤로 살며시 다가갑니다.\n\n\"그건 뭐야?\"","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159155","time":"2026-08-25T14:27:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"둠둠","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159156","time":"2026-08-25T14:28:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 허, 헉... 제가 만든 요, 요리에요. 같이 나, 나눠 드실래요? \"\n\n지글지글, 잘 구워진 고기 덩어를 모두에게 보여주며.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159157","time":"2026-08-25T14:32:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 오우. 뭐야. 돼지고기? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159158","time":"2026-08-25T15:38:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 은화 한 개 바, 반에 이만큼 파, 팔길래 얼른 집어왔죠! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159159","time":"2026-08-25T17:14:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"맛있는 향기가 솔솔 풍기는군!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159160","time":"2026-08-25T17:15:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"그런 그들의 뒤에 성큼성큼 나타나 우렁차게 외칩니다.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159162","time":"2026-08-25T17:25:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 한개 반에 이 정도라구? 싸게 잘샀네, 어디 얼굴 익혀둔 푸줏간이라도 있나봐. 나도 좀 먹어봐도 되쥐...? \"\n\n숀은 고기를 한 점... 와-앙-","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159163","time":"2026-08-25T17:30:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"거기, 꼬마 쥐! 이쪽에도 큼지막하게 던져줄 수 있겠나?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159164","time":"2026-08-25T17:38:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"마싯겟다...\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159165","time":"2026-08-25T17:38:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159166","time":"2026-08-25T17:57:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" ? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159167","time":"2026-08-25T18:35:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"누굴 얘기한 거야?","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159168","time":"2026-08-25T18:35:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 뒤를 돌아보았습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159169","time":"2026-08-25T18:55:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"폭풍처럼 몰아치는 쾌활한 미소가 숀을 바라봅니다.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159170","time":"2026-08-25T18:56:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"척봐도 댁이지!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159171","time":"2026-08-25T18:56:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"아, 신입이 들어왔구나.\"\n\n햄 찌를 바라보고 손을 흔듭니다.","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159172","time":"2026-08-25T18:58:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"여기 데미간이 또··· 저깄네. 저 친구는 말고.\"\n\n아르메리아와 같이 햄 찌를 보고 슬쩍 미소를 보이며 손을 흔듭니다.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159173","time":"2026-08-25T18:59:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 난 쥐가 아냐. 쥐-데미간이쥐. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159174","time":"2026-08-25T19:01:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"험. 그거나 저거나 같은 거 아닌가?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159175","time":"2026-08-25T19:01:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"방가방가!\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159176","time":"2026-08-25T19:03:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"아르메리아라고 해. 그쪽은?\"","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159177","time":"2026-08-25T19:07:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 찌푸린 얼굴로 로버트를 잠시 쳐다봤습니다.\n\n' 멍청한 애가 하나 더 늘었네. 쟤는 이제 패스. '\n\n\" 얜 햄 주니어. 그리고 햄, 얜 엘프 아르메리아야. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159178","time":"2026-08-25T19:07:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"쭈뼛쭈뼛. 주위를 둘러보며 천천히 들어옵니다. 곧 당신들을 보고 살짝 손을 흔들겠죠.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159179","time":"2026-08-25T19:08:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아르메리아? 이름 이쁘군. 그나저나 주방에 사람이 많구만? 다 요리하는거 도와주러 온 거지?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159180","time":"2026-08-25T19:09:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 아니 난 거덜내러 왔쥐. ㅋㅋ 근데 뒤에 쟈는 누구? \"\n\n숀은 엄지손가락으로 쑥, 아르케인을 가리켰습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159181","time":"2026-08-25T19:11:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"자존심이 꽤 구겨졌나 보군. 아하하하!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159182","time":"2026-08-25T19:11:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"알았어, 알았어. 미안하다구.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159183","time":"2026-08-25T19:11:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"서로 화해하는 의미로 통성명이나 할까?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159184","time":"2026-08-25T19:12:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ... \"\n\n멀리서 빗자루질을 하며 해머를 바라봅니다. \n\n이내 다시 고개를 떨구고 빗자루로 바닥을 쓸어 먼지를 모읍니다.","characters":["P-337878fc286e"]},{"id":"RP-III-0159185","time":"2026-08-25T19:12:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"움찔. 곧 옅은 미소. 부드럽게 웃으며 나긋나긋한 목소리로 말을 이어나갑니다.\n\"비올레타 아르케인이라 합니다. 새로 이 길드에 들어왔달까요. 만나서 반갑습니다 모두들.\"\n곧 부드러운 눈웃음과 함께 당신들을 흝어봅니다.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159186","time":"2026-08-25T19:13:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 신입인가보네- 그래, 모르는 거 있으면 저-기 저 고기 굽는 빨간머리 여자애한테 물어봐. 말은 좀 버벅여도, 할 일은 제대로 하는 녀석이거든! \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159187","time":"2026-08-25T19:14:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 고기 덩어리를 자르고 있는 @레마 캐롤라인 를 가르켰습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159188","time":"2026-08-25T19:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 뭐, 뭔가 도와 드릴거 있을까요? \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159189","time":"2026-08-25T19:17:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"꿈뻑. 느릿하게 눈을 감았다가 뜨더니. 곧 부드럽게 악수를 건넵니다.\n\"별건 아니고. 혹시 이곳에 저와 같은 엘프들이 많은지 궁금하네요. 가급적이면 다양한 분들을 만나보고 싶어서 물어보는거랍니다.\"","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159190","time":"2026-08-25T19:18:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"샤샤샤샥... 그렇게 일을 다 떠넘기고는 은밀하게 주방을 빠져나옵니다.","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159191","time":"2026-08-25T19:18:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159192","time":"2026-08-25T19:19:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 바, 반가워요. 엘프가 그렇게 마, 많은건 아니지만 인간 다, 다음으로는 많은 것 같더라구요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159193","time":"2026-08-25T19:19:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"엘프, 엘프, 엘프. 또 엘프군.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159194","time":"2026-08-25T19:19:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"덕분에 눈은 즐겁겠어!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159195","time":"2026-08-25T19:20:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" -ㅠ- ;; \"\n\n숀은 그 말에 다시 한 번 짜게 식었습니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159196","time":"2026-08-25T19:20:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그제야 빌미가 생겼다는 듯 천천히 다가가 인사를 건넵니다. \n\n\" ...좋은 저녁입니다. \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159197","time":"2026-08-25T19:21:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"해머 경, 혹시 고향에 인간밖에 없었어?\"","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159198","time":"2026-08-25T19:22:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"거의 인간 천지였지.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159199","time":"2026-08-25T19:22:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"어딜 가도 인간밖에 없었으니까.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159200","time":"2026-08-25T19:23:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"성에서도, 도시에서도, 마을에서도 말이지.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159201","time":"2026-08-25T19:23:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"그저 웃으며 당신을 바라봅니다.\n\"칭찬으로 받아들여야 하나요?\"","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159202","time":"2026-08-25T19:23:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"물론. 아주 곱고 아름답다는 말이니까. 거, 아가씨인지 도련님인지는 모르겠다만···\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159203","time":"2026-08-25T19:24:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"\"오호라. 그럼 가급적이면 그분들도 만나봐야겠네요. 정보 감사합니다. 후후.\"","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159204","time":"2026-08-25T19:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 엘프를 조, 좋아 하시는군요... 하하... \"\n\n당황스러운 얘기에 멋쩍게 웃으며, 본인은 엘프가 아니지만 좀 이상한 사람이라는 생각에 한 발짝 멀어진다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159205","time":"2026-08-25T19:24:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...여어.\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159206","time":"2026-08-25T19:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"햄스터다","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159207","time":"2026-08-25T19:25:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"오! 이번엔 티플링인가?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159208","time":"2026-08-25T19:25:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"\"으음. 엘프들이 아름답다는건..그쪽들 생각이겠지만은. 제 고향에 있는 동료들에게도 말해줄게요. 친절한 분들이 밖에도 많다고.\"\n후후. 웃음을 흘리며 당신을 바라보며 살짝 고개를 젖힙니다.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159209","time":"2026-08-25T19:25:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...반갑습니다. 샤온이라고 합니다. \"\n\n꼬리가 짧은... 쥐 데미간?\n조금 의아하지만. 허리를 고개를 60도쯤 꺾으며 인사합니다.","characters":["P-337878fc286e"]},{"id":"RP-III-0159210","time":"2026-08-25T19:25:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 네, 저는 티, 티플링이에요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159211","time":"2026-08-25T19:26:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 고향? 엘프들한테도 고향이 남았어? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159212","time":"2026-08-25T19:26:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이 발언을 잔느가 싫어합니다","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159213","time":"2026-08-25T19:27:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"그 미친 용이 죄다 불사르지 않았나? 나는 그렇게 들었는데 말이지.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159214","time":"2026-08-25T19:27:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"엥, 고개 숙일 것까지는 없는데.\"\n\n그의 정중한 인사에 조금 놀랍니다. 첫인상으로는 이런 인사를 기대하기 다소 힘든 모습이었기에...","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159215","time":"2026-08-25T19:28:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...아닙니다. 예의는 차려야 하니까요. \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159216","time":"2026-08-25T19:28:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"엘프나 드워프, 데미간들은 스쳐지나가듯이 봤었는데······ 티플링은 처음이군. 뿔 좀 만져봐도 괜찮겠나!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159217","time":"2026-08-25T19:28:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 고향이 그 엘프들의 고향 얘기가 아닌 것은 아닙니까? \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159218","time":"2026-08-25T19:29:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"아, 그런가!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159219","time":"2026-08-25T19:29:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"침묵. 무표정으로 잠시 당신들을 바라보다가 그저 창문밖을 봅니다. 씁쓸한 웃음을 지으며.\n\"..진짜 고향은 불탔죠.\"","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159220","time":"2026-08-25T19:29:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ... \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159221","time":"2026-08-25T19:30:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 어흠, 흠... 미안하다 괜한 소릴 했네...  크흠. 아! 저기 레마, 그래서. 고긴 언제 줄꺼야? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159222","time":"2026-08-25T19:30:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 조, 조금만 기다려요! \"\n\n다 졸아든 양파 사과 소스를 마지막으로 고기 위에 붓고 모두에게 나눠준다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159223","time":"2026-08-25T19:30:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"저 빨간 티플링의 이름이 레마인가?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159224","time":"2026-08-25T19:30:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 자, 여, 여기요. 다들 맛있게 드세요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159225","time":"2026-08-25T19:30:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"가만히 서서 숀에게 묻습니다.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159226","time":"2026-08-25T19:31:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...오, 저도 들어도 될까요? 좋은 냄새가 나는군요. \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159227","time":"2026-08-25T19:31:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 여, 여기요. \"\n\n다가가서 뿔을 내미는 레마.\n\n\" 잠시만이에요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159228","time":"2026-08-25T19:31:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 아무래도 요리에 일가견이 있으신가봅니다. \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159229","time":"2026-08-25T19:32:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그래도 나름 자, 자신 있어요. 마귀할멈 미, 밑에서 한참 배웠거든요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159230","time":"2026-08-25T19:32:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"아무런 망설임도 없이 콧김을 뿜어대며 레마의 뿔을 만지작거립니다! 이 촉감은··· 산양뿔? 꽤 기이한 감촉이로구만.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159231","time":"2026-08-25T19:32:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 의도적으로 로버트를 무시하고 있었습니다. 그가 쳐다보며 말을 걸어도, 숀은 그에게 등을 돌린채 레마와 일행들에게 말을 걸었습니다.\n\n\" 꽤나 솜씨가 있더라구. 너, 얘기 들어보니 카프리제도 인정 했담서?? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159232","time":"2026-08-25T19:32:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 마귀...? 그렇군요. 좋은 스승이었나봅니다. \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159233","time":"2026-08-25T19:33:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 이제 그, 그만... \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159234","time":"2026-08-25T19:33:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"···험. 거, 미안하다니까!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159235","time":"2026-08-25T19:33:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 마, 맞아요. 카프리제 씨에게 라, 라따뚜이를 만들어 드렸더니 이, 인정 해주시면서 좋은 말도 마, 많이 해 주셨어요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159236","time":"2026-08-25T19:34:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"그만이라는 소리를 듣자, 뿔에서 손을 놓습니다.\n\n\"만지게 해줘서 고맙군! 티플링은 이런 거에 민감하다고 들었는데.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159237","time":"2026-08-25T19:34:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그제서야 숀은 천천히 로버트를 돌아봤습니다.\n\n그리곤 아주 잠깐 대답하지 않고 로버트를 보며 인상을 찌푸렸습니다.\n\n\" 왜 소릴 질러? 너 나한테 용서 맡겨놨어? \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159238","time":"2026-08-25T19:35:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"다른 사람들이 그냥 만져볼 때랑은 뭔가 느낌이 다른 것 같아...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159239","time":"2026-08-25T19:35:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" 엇... \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159240","time":"2026-08-25T19:35:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...?\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159241","time":"2026-08-25T19:37:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"미안하니까 미안하다고 말하지! 그럼 뭐라고 말하냐?\"\n\n로버트의 입가에 머문 미소가 희마하게 사그라 들지만, 미안한 마음 자체는 진짜인 듯 힘을 실어 말합니다.","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159242","time":"2026-08-25T19:39:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"\"어머나.\"\n그저 미소를 유지하며 상황을 지켜봅니다. 생글생글. 미소를 유지하며.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159243","time":"2026-08-25T19:41:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"\" ...아무래도 자리를 비켜드리는게 나을까요? \"","characters":["P-337878fc286e"]},{"id":"RP-III-0159244","time":"2026-08-25T19:41:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"몸을 웅크려 햄스터 친구에게 속삭여봅니다.","characters":["P-337878fc286e"]},{"id":"RP-III-0159245","time":"2026-08-25T19:43:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 모른척 하고 싶은거야 아님 진짜 멍청한거야? \"\n\n숀은 로버트를 위 아래로 짧게 훑어봤습니다.\n\n\" 호탕한것과 무례한 건 달라. 난 너한테 이미 한 번 기회를 줬고, 넌 그 때도 '그게 그거 아니냐'며 어물쩍 넘어가려그랬어. 이제껏 네 시골 변두리 마을에선 네 덩치에 쫄아 어버버했던 촌뜨기들 뿐이 없었다면, 착각하쥐마. 여긴 도시고 길드야.\n\n너 같이 영웅 한 번 되겠다고 무턱대고 상경했다가 한계에 도착하면 약한 척, 세상 탓하며 돌아가는 애들. 한 둘 아니라고. \"\n\n그리곤 나무 컵을 탁-! 내려놓으며 의자에서 일어났습니다.\n\n\" 상처 받으라고 얘기하는 거야. 난 네 방식은 틀렸다고 생각하니까. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159246","time":"2026-08-25T19:44:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아무래도확실히\"","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159247","time":"2026-08-25T19:44:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"그리고 레마와 바올레타의 눈치를 봅니다. 고기 그릇을 든 채로요.","characters":["P-337878fc286e"]},{"id":"RP-III-0159248","time":"2026-08-25T19:45:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"ㅇㅁㅇ","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159249","time":"2026-08-25T19:45:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"설거지거리를 들고 조용히 주방 뒤편으로 사라져 개울로 도망가는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159250","time":"2026-08-25T19:45:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"...그리고 아르메리아도요.","characters":["P-337878fc286e"]},{"id":"RP-III-0159251","time":"2026-08-25T19:45:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"호다닥","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159252","time":"2026-08-25T19:45:00+09:00","room":"RP III","name":"햄 주니어","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-c6b8c16e2fba"]},{"id":"RP-III-0159253","time":"2026-08-25T19:46:00+09:00","room":"RP III","name":"샤온","profile":"스나가와 아이다","identity":"reviewed","type":"dialogue","body":"...그리고 그 또한 그들을 따라 움직여봅니다.","characters":["P-337878fc286e"]},{"id":"RP-III-0159254","time":"2026-08-25T19:46:00+09:00","room":"RP III","name":"아르메리아","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"슬금슬금 일어납니다.","characters":["P-d80a97449dfc"]},{"id":"RP-III-0159255","time":"2026-08-25T19:47:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"그저 웃음을 유지하다가 자리에서 일어나 천천히 싸우고 있는 둘 사이에 서더니.\n\"결국엔 우리 다 같은 길드원이잖아요. 진정하라고요.\"\n사근사근한 목소리로 웃으며 말합니다.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159256","time":"2026-08-25T19:50:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"입가에 머금은 웃음기가 어디로 가고, 안면은 타오르듯 붉게 불어집니다.\n\n자신과 숀 사이에 끼어든 작은 엘프를 보고 짦게 말합니다.\n\n\"···방금 사라진 놈들이랑 같이 나가있어. 저 작은 녀석이랑 내가 해결할 문제니까.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159257","time":"2026-08-25T19:53:00+09:00","room":"RP III","name":"비올레타 아르케인","profile":"비올레타 아르테인","identity":"reviewed","type":"dialogue","body":"그저 알수없는 부드러운 미소를 유지하며 끄덕이곤. 당신들을 바라봅니다.\n\"부디 당신들의 분쟁이 잘 해결되길.\"\n곧 유유히 자리를 떠나갑니다.","characters":["P-ecba2dd3a661"]},{"id":"RP-III-0159258","time":"2026-08-25T19:55:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그래~ 쳐라 쳐~ 너같은 놈들 한 둘 보냐~ \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159259","time":"2026-08-25T20:17:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"그 도발에 혹하고 넘어가, 저 쪼그만한 쥐의 죽통을 날리려 했습니다.\n\n하지만··· 멈추고 주저합니다. 자기가 그토록 꿈 꿨던 건, 주먹이나 휘두르는 무뢰배 따위가 아닙니다. 영웅이죠. 남을 수호하고 지키며, 남들의 환호와 찬사를 한 몸에 받는 찬란한 자. \n\n이야기 속 위대한 영웅은 남을 함부러 해하지 않습니다. 그리고 저 작은 친구의 역린을 괜히 건드리는 것 같기도 하고요. 그리 생각하면서 폭포수처럼 터져나온 성질을 간신히 진정한 로버트는 말합니다.\n\n\"미안하다. 내가··· 댁한테 실례가 될 말을 한 것 같군. 상처가 됐다면 진심으로 사과하겠다. 하지만···\"\n\n하지만 그의 굳센 자존심은 그것을 용납하지 않습니다. 자신에게 어떠한 타협이나 협상도 없으리라 단단히 믿고 있으니까요.\n\n\"댁이 내 꿈을 함부러 말하지 않았으면 좋겠군. 나는 내 방식으로 영웅이 될 거고, 세상에 이름을 알리며, 가장 높게 우뚝 설 거다. 댁이 틀렸다고 생각하든 말든 말이야!\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159260","time":"2026-08-25T20:33:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 의자를 박차고 일어난 뒤 자신에게 씩씩거리며 다가오는 로버트를 보았습니다.\n\n금방이라도 주먹을 날릴 기세에 숀은 그를 노려(올려다) 보았습니다.\n\n' ... 그래, 그럼 그렇지. '\n\n... 그러나 우뚝, 멈춰 선 로버트가 주먹 대신 선택한 건 사과였습니다.\n\n-미안하다.\n\n그것이 그의 첫마디 였습니다.\n\n숀은 그의 얘기를 주욱 들었습니다.\n그리고 대답했습니다.\n\n\" 처음엔 다들 그렇게 얘기해. 내 꿈에 대해 함부로 얘기 말아달라. 내 방식대로 우뚝 서겠다. 하지만 그 얘긴 천천히 변하쥐.\n\n처음엔 '내 생각과 다르다' \n\n그리고 동료를 잃고서야,\n\n...이렇게까지 될 줄은 몰랐다. 라고 말야.\n\n상처 줘서 미안하다. 하지만 영웅이 되려거든 공부 먼저 해. 다시 말하쥐만 여긴 도시야. 온 천지에 시골에서 나잘났다는 녀석들이 모이고, 그리고 그 중 8할은 크게 다치거나 누굴 잃어서 돌아가. \"","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159261","time":"2026-08-25T21:10:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"······그래. 그렇지. 나도 그걸··· 댁처럼 몇 번 봤었으니까.\"\n\n종자 시절, 눈에 담았었던 전장. 자기 이름 하나 남기지 못한 채 축축하고 차가운 진흙탕에서 죽어나간 사내들. 굳건한 기사들의 갑옷이 찌그러지고, 오물에 잠겨 숨을 거둔 기사들.\n\n\"······그 영웅 공부란 거, 까짓거 하겠어. 하나하나 전부 습득해서 영웅 중의 영웅. 누구보다 위대지겠다고. 훗날의 댁이 봐도, 성에 차는 그런 영웅으로 말이야.\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159262","time":"2026-08-25T21:12:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"\"계속 댁이라고 하기엔 좀 그렇고. 통성명이나 할까?\"","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159263","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"로버트 해머","profile":"록시","identity":"reviewed","type":"dialogue","body":"!fin","characters":["P-6702f2f42aad"]},{"id":"RP-III-0159264","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"숀은 다시 한 번 통성명을 하자는 로버트의 물음에 싱긋 웃으며 대답했습니다.\n\n쥐 아니고, 쥐 데미간.\n\n\" ...숀! '사우스 풋', 숀...! \"\n\n꽤, 괜찮은 신입이 들어왔다.\n\n고 생각하며 말입니다.","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159265","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"숀 사우스 풋","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5c88d36f51cd"]},{"id":"RP-III-0159266","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-III-0159267","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"은근슬쩍 들어와서 설거지거리를 가지고 다시 나가는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159268","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fec1db60d51e"]},{"id":"RP-III-0159269","time":"2026-08-25T21:15:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
